import mongose from"mongoose";const orderSchema=new mongose.Schema({userId:{type:String,required:!1},items:{type:Array,required:!0},orderNumber:{type:String,required:!0},amount:{type:Number,required:!0},address:{type:Object,required:!0},status:{type:String,required:!0,default:"Order Placed"},paymentMethod:{type:String,required:!0},payment:{type:Boolean,required:!0,default:!1},trackingNumber:{type:String,required:!1},redsysOrder:{type:String},date:{type:Number,required:!0}}),orderModel=mongose.models.order||mongose.model("order",orderSchema);export default orderModel;